const DYN: Record<string, [number, number]> = {
  sui: [581, 618], tang: [618, 907], wudai: [907, 960], beisong: [960, 1127], nansong: [1127, 1279],
  yuan: [1279, 1368], ming: [1368, 1644], qing: [1644, 1912], roc: [1912, 1949], prc: [1949, 2027],
};

const i18n = (zh: string, en: string): I => ({ zh, en });

export const SETTLEMENTS_LATE: Content['settlements'] = [...Object.entries(L), ...Object.entries(L2)].flatMap(([dyn, list]) =>
  list.map(([site, zh, en, from, to, flags = '', nzh, nen]) => {
    const s = S[site];
    if (!s) throw new Error(`places-late: unknown site ${site}`);
    const [a, b] = DYN[dyn];
    return {
      dyn, name: i18n(zh, en), modern: i18n(s[0], s[1]), lon: s[2], lat: s[3], from: from || a, to: to || b,
      ...(flags.includes('c') ? { capital: true } : {}), ...(flags.includes('m') ? { minor: true } : {}),
      ...(nzh ? { note: i18n(nzh, nen ?? '') } : {}),
    };
  }));

/** city lore: [site, tag zh, tag en, desc zh, desc en] */
const CL: [string, string, string, string, string][] = [
  ['xa', '十三朝古都 · 丝路起点', 'Capital of thirteen dynasties · start of the Silk Road', '西周、秦、西汉、隋、唐等王朝都在这一带建都，关中平原四面有山河屏障，被视为“天府之国”。唐长安城规模宏大，日本、新罗的使节和中亚的商人都在此汇聚。唐以后政治中心东移，它成为控制西北的重镇。', 'The Western Zhou, Qin, Western Han, Sui and Tang all ruled from this stretch of the Wei valley, a basin ringed by mountains and rivers. Tang Chang\'an was vast and drew envoys from Japan and Silla and merchants from Central Asia. After the Tang the centre of power moved east and the city became the key to the north-west.'],
  ['ly', '天下之中 · 九朝古都', 'Centre of the realm · capital of nine dynasties', '洛阳居黄河中游，被古人视为“天下之中”，东周、东汉、曹魏、西晋、北魏等相继建都。佛教初传中国时的白马寺、北魏开凿的龙门石窟都在这里。隋唐时它是大运河的枢纽和东都。', 'On the middle Yellow River, Luoyang was thought of as the centre of the world and served the Eastern Zhou, Eastern Han, Wei, Western Jin and Northern Wei as capital. The White Horse Temple of the first Buddhist missions and the Northern Wei Longmen caves are here. Under the Sui and Tang it was the hub of the Grand Canal and the Eastern Capital.'],
  ['kf', '八朝古都 · 汴京繁华', 'Capital of eight dynasties · the splendour of Bianjing', '战国魏都大梁就在此地，五代多个王朝和北宋都以它为京城。北宋东京依汴河漕运养活上百万人口，《清明上河图》描绘的就是它的街市。黄河多次泛滥，古城层层叠压在今天的地下。', 'The Warring States Wei capital of Daliang stood here, and several Five Dynasties regimes and the Northern Song ruled from it. Song Kaifeng fed a million people on grain brought by the Bian Canal, and its streets are the scene of the Qingming scroll. Repeated Yellow River floods have buried the old cities layer upon layer.'],
  ['nj', '六朝古都 · 江南重镇', 'Capital of six dynasties · bastion of the south', '孙吴、东晋和南朝宋齐梁陈都在这里建都，史称六朝。明初定都于此，修筑了周长三十多公里的城墙，太平天国和中华民国也以此为都。它控扼长江下游，是南方政权的天然中心。', 'The Wu, Eastern Jin and the four Southern Dynasties made it their capital, the "Six Dynasties". The early Ming built its huge wall here, and the Taiping and the Republic later ruled from it too. Commanding the lower Yangtze, it was the natural centre of any southern regime.'],
  ['hz', '人间天堂 · 南宋行在', 'Paradise on earth · seat of the Southern Song', '杭州在隋代因江南运河而兴，吴越国在此建都。南宋以它为“行在”，人口过百万，商业与手工业极其繁荣。西湖经白居易、苏轼等人治理，成为文人吟咏不尽的风景。', 'Hangzhou grew with the Sui Jiangnan Canal and became the Wuyue capital. The Southern Song made it their seat, a city of over a million people and booming trade and crafts. West Lake, tended by governors such as Bai Juyi and Su Shi, became a landscape poets never tired of.'],
  ['bj', '元明清三朝帝都', 'Imperial capital of the Yuan, Ming and Qing', '这里古称蓟，是燕国的都城，后来长期是北方边防重镇。辽以此为南京，金在此建中都，元建大都，明清两代以此为京师，紫禁城就是明代营建的。1949年起它成为中华人民共和国的首都。', 'Called Ji in antiquity and the capital of the state of Yan, it was long a frontier bastion. The Liao made it their Southern Capital, the Jin their Central Capital and the Yuan built Dadu; the Ming and Qing ruled from it, and the Forbidden City is Ming work. Since 1949 it has been the capital of the People\'s Republic.'],
  ['ty', '龙城晋阳', 'Jinyang, the dragon city', '太原古称晋阳，是春秋晋国赵氏的根据地，也是北齐的别都。李渊父子由此起兵建立唐朝，所以唐人称它为北都。五代时它几度成为王朝兴起的根据地，北宋灭北汉后才毁旧城另建新城。', 'Ancient Jinyang was the base of the Zhao clan of Jin and a second capital of the Northern Qi. Li Yuan and his sons rose from here to found the Tang, which called it the Northern Capital. Several Five Dynasties regimes rose from it, until the Song destroyed the old city and built a new one.'],
  ['yz', '淮左名都 · 运河咽喉', 'Famed city of the Huai · throat of the canal', '扬州在春秋时有邗城，吴王夫差在此开凿邗沟。隋炀帝开大运河后，它成为南北物资的集散地，唐代有“扬一益二”的说法。清代两淮盐商聚居于此，园林和戏曲盛极一时。', 'Yangzhou began as Han city, where King Fuchai of Wu dug the Han canal. After the Sui Grand Canal it became the clearing-house between north and south, first among Tang cities. In the Qing the Lianghuai salt merchants made it a city of gardens and opera.'],
  ['sz', '园林之城 · 吴文化中心', 'City of gardens · heart of Wu culture', '春秋吴国以此为都，传为伍子胥筑城，城址延续两千五百年少有变动。宋代起它是全国最富庶的地区之一，明清时丝织业发达、文人辈出。城中古典园林是江南文人生活的缩影。', 'The Wu kingdom\'s capital, walled by tradition under Wu Zixu, has kept its site for two and a half thousand years. From the Song it was among the richest places in China, and in Ming and Qing times a city of silk and scholars. Its classical gardens distil the life of the southern literati.'],
  ['cd', '天府之国 · 锦官城', 'Land of abundance · the brocade city', '成都自古是蜀地中心，都江堰使成都平原旱涝保收，号称天府。三国蜀汉、五代前后蜀都在此建都，蜀锦和北宋的交子都诞生于此。杜甫草堂与武侯祠是它的人文名片。', 'Chengdu has always been the centre of Shu, and the Dujiangyan irrigation made its plain famine-proof. Shu Han and the Former and Later Shu ruled from here, and Shu brocade and the Song paper money both began here. Du Fu\'s cottage and the shrine of Zhuge Liang are its landmarks.'],
  ['gz', '千年商都 · 南海门户', 'A trading city for two thousand years · gate to the southern sea', '秦末赵佗在番禺建立南越国。唐宋时它是海上丝绸之路的大港，蕃坊里住满阿拉伯和波斯商人。清代一口通商时期，十三行垄断对西方的贸易，近代又是革命的策源地。', 'Zhao Tuo founded the Nanyue kingdom at Panyu here at the end of the Qin. Under the Tang and Song it was a great port of the maritime Silk Road with a foreign quarter of Arab and Persian traders. In the Qing it was the one port for Western trade and later the cradle of revolution.'],
  ['qz', '刺桐港 · 海丝起点', 'Zayton · a starting point of the maritime Silk Road', '泉州在五代时遍植刺桐，外国商人称之为刺桐城。宋元时期它与亚非数十国通商，是当时世界上最大的港口之一，城中留下清真寺、印度教石刻等多元遗迹。明代海禁后逐渐衰落。', 'Planted with coral trees in the tenth century, Quanzhou was known to foreigners as Zayton. In the Song and Yuan it traded with dozens of countries and was among the largest ports in the world, leaving mosques and Hindu carvings behind. The Ming sea bans brought its decline.'],
  ['fz', '榕城 · 闽都', 'Banyan City · capital of Min', '福州古称冶城，汉初闽越王无诸在此建都。五代王审知建闽国，城中遍植榕树。近代马尾船政局在这里创办，培养了中国第一代近代海军。', 'Called Ye city in antiquity, it was the capital of Wuzhu, king of Minyue, in the early Han. Wang Shenzhi founded the Min kingdom here and planted banyans throughout. In modern times the Mawei Navy Yard trained China\'s first modern navy.'],
  ['cs', '楚汉名城 · 湖湘中心', 'City of Chu and Han · heart of Hunan', '长沙在秦汉时是长沙郡、长沙国的治所，马王堆汉墓出土了大量帛书与漆器。唐代长沙窑彩瓷远销海外，宋代岳麓书院名闻天下。近代湖湘人才辈出，长沙是他们的摇篮。', 'Changsha was the seat of a Qin commandery and a Han kingdom, and the Mawangdui tombs yielded silk manuscripts and lacquer. Its Tang painted ware sold overseas and the Song Yuelu Academy was famous. In modern times it nurtured a remarkable generation of Hunanese leaders.'],
  ['wh', '九省通衢 · 江城', 'Thoroughfare of nine provinces · the river city', '长江与汉水在此交汇，武昌、汉口、汉阳三镇隔江鼎立。汉口在明清时成为全国最大的商业重镇之一，近代张之洞在此兴办铁厂、纱厂。1911年武昌起义爆发，推翻了帝制。', 'Here the Han meets the Yangtze, and the three towns of Wuchang, Hankou and Hanyang face each other across the water. Hankou became one of the great marts of Ming and Qing China, and Zhang Zhidong built ironworks and mills here. The Wuchang uprising of 1911 brought down the empire.'],
  ['jingzhou', '楚都故地 · 兵家必争', 'Old land of Chu · fought over by every general', '附近的纪南城是楚国都城郢的所在。三国时荆州是魏、蜀、吴反复争夺的焦点，关羽大意失荆州的故事家喻户晓。江陵城墙至今保存完好。', 'Nearby Jinan city was Ying, the Chu capital. In the Three Kingdoms Jingzhou was the prize fought over by Wei, Shu and Wu, and the tale of Guan Yu losing it is known to all. The walls of Jiangling still stand complete.'],
  ['xy', '铁打的襄阳', 'Iron Xiangyang', '襄阳据汉水中游，北通中原、南控荆楚，是南北对峙时的门户。南宋军民在此抵抗元军围攻近六年，城破后南宋迅速瓦解。诸葛亮隐居的隆中就在城西。', 'On the middle Han, linking the central plain with the south, Xiangyang was the gateway in every north–south war. The Song held it against the Mongols for nearly six years, and when it fell the dynasty collapsed. Zhuge Liang\'s retreat at Longzhong lies just west.'],
  ['nc', '豫章故郡 · 洪都新府', 'Old Yuzhang · new Hongdu', '南昌汉代为豫章郡治，唐代称洪州，王勃《滕王阁序》使这里名扬天下。1927年八一南昌起义在此爆发，被视为人民军队的诞生。', 'Seat of Yuzhang commandery under the Han and Hongzhou under the Tang, it was made famous by Wang Bo\'s preface on the Tengwang Pavilion. The Nanchang uprising of 1 August 1927 is counted as the birth of the People\'s army.'],
  ['jiujiang', '江南门户 · 庐山脚下', 'Gate of the south · foot of Mount Lu', '九江扼长江与鄱阳湖的交汇处，古称浔阳、江州。陶渊明在附近归隐，白居易在此写下《琵琶行》，庐山的白鹿洞书院是宋代理学的重镇。', 'Where the Yangtze meets Lake Poyang, it was known as Xunyang and Jiangzhou. Tao Yuanming retired nearby, Bai Juyi wrote his Song of the Pipa here, and the White Deer Grotto Academy on Mount Lu was a centre of Song Neo-Confucianism.'],
  ['jdz', '千年瓷都', 'Porcelain capital for a thousand years', '景德镇因北宋景德年间进贡瓷器而得名。元代青花瓷在此成熟，明清设御窑厂专为宫廷烧瓷，产品行销世界。它是中国瓷器的代名词。', 'Named after the Jingde reign, when it sent porcelain to the Song court. Blue-and-white matured here under the Yuan, and Ming and Qing imperial kilns fired for the palace and the world. Its name became a byword for Chinese porcelain.'],
  ['hefei', '淮右襟喉 · 江南唇齿', 'Throat of the Huai · shield of the south', '合肥地处江淮之间，三国时张辽在逍遥津以少胜多，曹魏与孙吴在此反复交锋。北宋包拯是合肥人。1945年后成为安徽省会，今天以科教闻名。', 'Between the Yangtze and the Huai, it saw Zhang Liao\'s famous stand at Xiaoyaojin and endless Wei–Wu fighting. Bao Zheng of the Song was a native. Capital of Anhui since 1945, it is now known for science and education.'],
  ['shouxian', '楚国末都 · 淝水古战场', 'Last capital of Chu · the Fei River battlefield', '寿春是战国晚期楚国的最后都城，也是淮南王刘安的封国所在。383年淝水之战在城外进行，东晋以少胜多击败前秦。宋代城墙保存至今。', 'Shouchun was the last capital of Chu and the seat of Liu An, King of Huainan. The battle of the Fei River in 383, when the Eastern Jin routed the Former Qin, was fought outside its walls. Its Song walls still stand.'],
  ['shexian', '徽商故里', 'Homeland of the Huizhou merchants', '歙县是古徽州府的治所。这里山多田少，男子多外出经商，明清徽商富甲一方，又重视教育，造就了徽派建筑、新安画派和徽墨歙砚。', 'Shexian was the seat of old Huizhou. With little farmland, its men went off to trade; the Ming and Qing Huizhou merchants grew rich and poured money into learning, leaving Hui architecture, the Xin\'an painters, and famous ink and inkstones.'],
  ['anqing', '万里长江此封喉', 'Where the Yangtze can be closed', '安庆扼长江下游的要冲，南宋末年建城后就是军事重镇。太平天国战争中湘军攻下安庆，打开了进攻天京的大门。曾国藩在此创办内军械所，造出中国第一台蒸汽机。', 'Commanding the lower Yangtze, Anqing was a fortress from its founding in the late Song. The Hunan Army\'s capture of it opened the road to the Taiping capital. Zeng Guofan set up an arsenal here that built China\'s first steam engine.'],
  ['xuzhou', '五省通衢 · 兵家必争', 'Crossroads of five provinces · prize of every war', '徐州古称彭城，是汉高祖刘邦的故乡，项羽曾以此为西楚都城。它处在南北交通的要道上，历代大战频繁，1948年淮海战役也在其周围展开。', 'Ancient Pengcheng was the home of Liu Bang, founder of the Han, and the capital of Xiang Yu\'s Western Chu. On the main north–south road, it saw countless battles, including the Huaihai campaign of 1948.'],
  ['sq', '商丘 · 宋国故都', 'Shangqiu · old capital of Song', '商丘相传是商人的起源地，西周时是宋国的都城。北宋太祖曾任归德军节度使，因此以“宋”为国号，并在此设南京应天府，应天书院是宋代四大书院之一。', 'By tradition the cradle of the Shang people, it was the capital of the Zhou state of Song. The Song founder had governed here, hence his dynasty\'s name; it became the Southern Capital, and its Yingtian Academy was one of the great Song academies.'],
  ['zz', '商都 · 铁路枢纽', 'A Shang city · railway hub', '郑州商城遗址是商代前期的大型都邑。近代京汉、陇海铁路在此交会，城市迅速发展，1954年成为河南省会。', 'The Shang city at Zhengzhou was one of the great early Shang centres. Modern railways crossing here made it grow fast, and it became the capital of Henan in 1954.'],
  ['ay', '殷墟 · 甲骨文故乡', 'Yinxu · home of the oracle bones', '商王盘庚迁殷后，这里作为商朝都城两百余年。1899年甲骨文被认出，1928年起的考古发掘证实了商代历史。附近的邺城是曹魏和北朝多个王朝的都城。', 'After King Pangeng moved here, it was the Shang capital for over two centuries. Oracle bones were recognised in 1899 and excavations from 1928 confirmed Shang history. Nearby Ye was the capital of the Cao Wei and several Northern Dynasties.'],
  ['hd', '赵都邯郸', 'Handan, capital of Zhao', '邯郸是战国赵国的都城，胡服骑射、完璧归赵、负荆请罪等故事都发生在这里。它在汉代仍是全国大城，后来逐渐衰落。', 'Handan was the capital of Zhao in the Warring States, where tales like "returning the jade intact" and "carrying the thorns" took place. Still a great city under the Han, it later faded.'],
  ['zd', '常山古郡 · 燕赵重镇', 'Old Changshan · stronghold of Yan-Zhao', '正定是三国赵云的故乡，唐代成德节度使驻此，宋代为河北西路重镇。隆兴寺等古建筑保存完好，号称“古建筑博物馆”。', 'Zhengding was the home of Zhao Yun of the Three Kingdoms, seat of the Tang Chengde governors and a Song bastion. Its Longxing Temple and other buildings make it a museum of old architecture.'],
  ['tj', '津门 · 北方商埠', 'Tianjin · the north\'s trading port', '天津因运河漕运而兴，明代设卫筑城。1860年开埠后九国租界并立，洋务企业和北洋军队都以此为基地，是近代中国北方最开放的城市。', 'Tianjin grew on the canal grain trade and was walled as a Ming garrison. Opened in 1860, it held nine foreign concessions and was the base of modern industry and the Beiyang army, the most open city of the north.'],
  ['datong', '北魏平城 · 辽金西京', 'Pingcheng of the Northern Wei · Western Capital of Liao and Jin', '北魏前期在此建都，开凿了云冈石窟。辽金两朝以它为西京，留下华严寺、善化寺等建筑。明代它是九边重镇，长城就在城北。', 'The early Northern Wei ruled from here and carved the Yungang caves. The Liao and Jin made it their Western Capital, leaving temples such as Huayan. In the Ming it was one of the Nine Borders, with the Wall just north.'],
  ['xianyang', '秦都咸阳', 'Xianyang, capital of Qin', '秦孝公迁都咸阳后，这里成为秦统一天下的中心。秦始皇在此营建宫殿，咸阳原上分布着西汉帝陵。秦末项羽焚烧咸阳，大火三月不灭。', 'After Duke Xiao moved the Qin capital here it became the centre from which Qin united China. The First Emperor built his palaces here, and the Western Han tombs line the plateau. Xiang Yu burnt the city at the end of the Qin.'],
  ['hanzhong', '汉家发祥地', 'Where the Han began', '刘邦被封为汉王，以汉中为根据地，后来国号就叫“汉”。三国时诸葛亮多次从这里北伐。它夹在秦岭和大巴山之间，是川陕交通的枢纽。', 'Liu Bang was made King of Han with Hanzhong as his base, and his dynasty took its name. Zhuge Liang launched his northern campaigns from here. Between the Qinling and Daba ranges, it links Shaanxi and Sichuan.'],
  ['yanan', '革命圣地', 'Holy land of the revolution', '延安古称肤施、延州，北宋时是抗击西夏的前线。1937至1947年中共中央驻此，领导抗日战争，宝塔山成为这一时期的象征。', 'Old Fushi and Yanzhou, it was a Song front line against the Xi Xia. From 1937 to 1947 the Communist leadership was based here, and its pagoda hill became the symbol of that era.'],
  ['lz', '金城 · 黄河之滨', 'Jincheng · on the Yellow River', '兰州是黄河穿城而过的城市，汉代称金城，是通往河西走廊的门户。清代甘肃省会设于此，1909年建成的中山铁桥是黄河上第一座铁桥。', 'The Yellow River runs right through Lanzhou, called Jincheng under the Han and gateway to the Hexi Corridor. It became the Gansu capital in the Qing, and its iron bridge of 1909 was the first on the Yellow River.'],
  ['tianshui', '羲皇故里', 'Home of Fuxi', '天水古称秦州、上邽，相传是伏羲的故里，秦人的祖先也在这一带兴起。麦积山石窟是中国四大石窟之一。', 'Ancient Qinzhou and Shanggui, Tianshui is by tradition the home of Fuxi, and the ancestors of the Qin rose nearby. The Maijishan caves are among China\'s four great grottoes.'],
  ['wuwei', '凉州 · 河西都会', 'Liangzhou · metropolis of the Hexi Corridor', '武威古称姑臧、凉州，汉武帝时设郡，以彰显武功军威。五凉政权多在此建都，唐代凉州是丝路上的大都会，出土的铜奔马成为中国旅游的标志。', 'Called Guzang and Liangzhou, it was a Han commandery named for martial glory. Most of the Five Liang states ruled from here, the Tang city was a great Silk Road market, and its bronze galloping horse became China\'s tourism emblem.'],
  ['zhangye', '张国臂掖 · 金张掖', 'Arm of the empire · golden Zhangye', '张掖之名取“张国之臂掖”，是汉代河西四郡之一。609年隋炀帝在此会见西域二十七国使者。明代甘肃镇驻此，城中有全国最大的室内卧佛。', 'Its name means "the empire\'s outstretched arm"; it was one of the four Han commanderies of the Corridor. In 609 Emperor Yang of the Sui met envoys of twenty-seven western states here. In the Ming it was the Gansu command, and its temple holds China\'s largest indoor reclining Buddha.'],
  ['jiuquan', '酒泉 · 河西西门', 'Jiuquan · west gate of the Corridor', '相传霍去病把汉武帝赏赐的酒倒入泉中与将士共饮，城因此得名。它是汉代河西四郡之一，西边的嘉峪关是明长城的西端。今天这里以卫星发射中心闻名。', 'By legend Huo Qubing poured the emperor\'s gift of wine into a spring to share with his men, giving the city its name. One of the four Han commanderies, it lies east of the Jiayu Pass at the Ming Wall\'s end, and today lends its name to a launch centre.'],
  ['dunhuang', '敦煌 · 莫高窟', 'Dunhuang · the Mogao caves', '敦煌是汉代河西四郡最西的一郡，阳关、玉门关在其西。从十六国到元代，莫高窟开凿了七百多个洞窟。1900年发现的藏经洞文书催生了“敦煌学”。', 'The westernmost of the Han commanderies, with the Yang and Jade Gate passes beyond it. From the fourth to the fourteenth century over seven hundred caves were cut at Mogao. The documents of the Library Cave, found in 1900, created the field of Dunhuang studies.'],
  ['gaochang', '高昌故城', 'The ancient city of Gaochang', '高昌是吐鲁番盆地的古城，曾是麴氏高昌国的都城，玄奘西行时在此讲经。640年唐灭高昌设西州，后来又成为回鹘高昌王国的都城。', 'Gaochang was the old city of the Turpan basin and capital of the Qu kingdom, where Xuanzang preached on his way west. The Tang made it Xizhou in 640; later it was the capital of the Uighur kingdom of Qocho.'],
  ['kashgar', '丝路南北道交汇', 'Where the Silk Roads met', '喀什古称疏勒，是塔里木盆地西缘的绿洲，唐代安西四镇之一。它连接帕米尔高原与中亚，喀喇汗王朝时期是伊斯兰文化的中心。', 'Ancient Shule, an oasis on the western rim of the Tarim, was one of the Tang Four Garrisons. Linking the Pamirs and Central Asia, it became a centre of Islamic culture under the Karakhanids.'],
  ['khotan', '于阗 · 美玉之乡', 'Yutian · land of jade', '于阗是塔里木盆地南缘的古国，以出产美玉著称，玉石很早就东运中原。它是佛教东传的重要中转站，唐代列为安西四镇之一。', 'Yutian, on the southern edge of the Tarim, was famous for jade, which travelled east from very early times. It was a key relay for Buddhism coming east and one of the Tang Four Garrisons.'],
  ['kuqa', '龟兹 · 西域乐舞之乡', 'Kucha · home of western music and dance', '龟兹是天山南麓的大国，唐代安西都护府驻此。高僧鸠摩罗什出生于此，龟兹乐舞传入中原后深刻影响了隋唐音乐。克孜尔千佛洞是这一时期的遗存。', 'Kucha, a great state south of the Tianshan, was seat of the Tang Anxi Protectorate. The monk Kumārajīva was born here, and Kuchean music reshaped Sui–Tang court music. The Kizil caves preserve its art.'],
  ['urumqi', '天山北麓的新城', 'A new city north of the Tianshan', '清代平定准噶尔后在此筑城，取名迪化。1884年新疆建省，迪化成为省会，1954年改名乌鲁木齐。它是今天新疆的政治经济中心。', 'The Qing walled a town here after defeating the Zunghars and called it Dihua. It became the capital when Xinjiang was made a province in 1884 and was renamed Ürümqi in 1954. It is today the centre of Xinjiang.'],
  ['huiyuan', '伊犁将军府', 'Seat of the Ili general', '乾隆年间在伊犁河畔修筑惠远城，伊犁将军驻此统辖天山南北。林则徐被贬后曾在此兴修水利。俄国侵占伊犁后城被毁，后又在附近重建。', 'Under Qianlong Huiyuan was built on the Ili River as the seat of the general who ruled all Xinjiang. Lin Zexu worked on irrigation here in exile. Destroyed during the Russian occupation, it was rebuilt nearby.'],
  ['lhasa', '日光城 · 雪域圣城', 'City of sunlight · holy city of the snows', '七世纪松赞干布在此建立吐蕃王朝，文成公主入藏后修建了大昭寺。十七世纪起这里是达赖喇嘛的驻地，布达拉宫高踞红山之上。1727年清朝设驻藏大臣。', 'Songtsen Gampo founded the Tibetan empire here in the seventh century, and the Jokhang was built after Princess Wencheng arrived. From the seventeenth century it was the seat of the Dalai Lama, with the Potala above. The Qing posted residents here from 1727.'],
  ['shigatse', '后藏中心', 'Centre of Tsang', '日喀则是后藏的中心，扎什伦布寺是历代班禅喇嘛的驻锡地。它附近的萨迦寺在元代曾代表朝廷管理西藏。', 'The centre of western Tibet, it is home to Tashilhunpo, seat of the Panchen Lamas. Nearby Sakya governed Tibet on behalf of the Yuan court.'],
  ['xining', '河湟重镇', 'Bastion of the Huangshui', '西宁古称青唐，北宋时是唃厮啰政权的中心，1104年改名西宁。它是汉、藏、回等民族交汇之地，附近的塔尔寺是藏传佛教格鲁派的名寺。', 'Called Qingtang, it was the centre of the Tibetan Gusiluo state until the Song renamed it Xining in 1104. A meeting place of Han, Tibetans and Hui, it lies near Kumbum, a great Gelug monastery.'],
  ['yinchuan', '西夏故都 · 塞上江南', 'Xi Xia capital · a southland beyond the passes', '银川是西夏的都城兴庆府，城西有西夏王陵。黄河灌溉使这里稻田遍布，被称为“塞上江南”。元代改称宁夏，宁夏之名由此而来。', 'Yinchuan was Xingqing, capital of the Xi Xia, whose royal tombs lie to the west. Yellow River irrigation fills it with paddies, a "southland beyond the passes". The Yuan named it Ningxia, the origin of the region\'s name.'],
  ['hohhot', '青城 · 归化', 'The Blue City · Guihua', '明代蒙古土默特部首领阿勒坦汗在此筑城，明朝赐名归化。清代又在旁边修筑绥远城驻军，旅蒙商人以此为基地。今天是内蒙古自治区首府。', 'Altan Khan of the Tümed built a city here that the Ming named Guihua. The Qing added the garrison town of Suiyuan, and the Mongolian trade was run from here. It is now the capital of Inner Mongolia.'],
  ['chengde', '避暑山庄', 'The Mountain Resort', '康熙帝在此营建避暑山庄，清帝每年夏秋来此处理政务、接见蒙古和西藏的首领。周围的外八庙融合了汉藏建筑风格。1793年乾隆帝在此接见英国使团。', 'The Kangxi emperor built the Mountain Resort here, where Qing emperors spent summers governing and receiving Mongol and Tibetan lords. The Eight Outer Temples mix Han and Tibetan styles. Qianlong received the British embassy here in 1793.'],
  ['shenyang', '一朝发祥地 · 两代帝王城', 'Cradle of a dynasty', '1625年努尔哈赤迁都沈阳，皇太极改名盛京并在此改国号为清。清入关后盛京为陪都，故宫至今保存。近代它是奉系军阀的大本营，1931年九一八事变从这里开始。', 'Nurhaci moved his capital here in 1625, and Hong Taiji renamed it Shengjing and proclaimed the Qing. After 1644 it stayed a secondary capital, and its palace survives. It was later the Fengtian warlords\' base, and the Mukden Incident of 1931 began here.'],
  ['liaoyang', '辽东古城', 'Old city of Liaodong', '辽阳在战国燕时设辽东郡，此后长期是东北的政治中心。辽代为东京，明代辽东都司驻此，努尔哈赤攻占后一度在此建都。', 'Liaoyang was the seat of Liaodong commandery from the state of Yan onwards, the long-time centre of the north-east. It was the Liao Eastern Capital and seat of the Ming Liaodong command, and Nurhaci briefly ruled from it.'],
  ['jilin', '船厂 · 雾凇之城', 'The Shipyard · city of rime ice', '清初为抗击沙俄在松花江边造船，因此得名船厂，吉林将军驻此。冬季江边的雾凇是著名的景观。', 'In the early Qing ships were built here on the Sungari to resist Russia, giving the town its name; the Jilin general was based here. Its winter rime ice on the riverside trees is famous.'],
  ['harbin', '冰城 · 东方莫斯科', 'Ice city · the Moscow of the East', '哈尔滨随着1898年开始修建的中东铁路而兴起，俄国人和各国侨民聚居，留下了大量欧式建筑。今天它以冰雪节闻名。', 'Harbin rose with the Chinese Eastern Railway from 1898, settled by Russians and others who left their European buildings. Today it is known for its ice festival.'],
  ['lushun', '军港旅顺', 'The naval port of Lüshun', '旅顺是北洋水师的军港，甲午战争中被日军攻陷。此后俄国、日本先后占据，1904年日俄战争在此激战。它见证了近代中国的屈辱与抗争。', 'Lüshun was the Beiyang Fleet\'s base, stormed by Japan in 1894. Russia and Japan took it in turn, fighting a great siege here in 1904. It bears witness to modern China\'s humiliations and resistance.'],
  ['jinan', '泉城', 'City of springs', '济南因在济水之南得名，城中有趵突泉等七十二名泉，号称泉城。李清照、辛弃疾都是济南人，明清时为山东省会。', 'Named for lying south of the Ji River, it has seventy-two famous springs such as Baotu. Li Qingzhao and Xin Qiji were natives, and it was the Shandong capital in Ming and Qing.'],
  ['qingzhou', '古九州之一', 'One of the ancient Nine Provinces', '青州是《禹贡》九州之一，汉以后长期是山东东部的政治中心。它出土的北朝佛教造像以精美闻名。', 'Qingzhou is one of the Nine Provinces of the Tribute of Yu and was long the centre of eastern Shandong. Its Northern Dynasties Buddhist statues are celebrated.'],
  ['penglai', '登州港 · 仙境传说', 'Port of Dengzhou · land of immortals', '蓬莱古为登州，是唐宋时期通往朝鲜半岛和日本的港口。秦皇汉武曾到这一带求仙，蓬莱阁的海市蜃楼传说流传千年。明代戚继光在此训练水师。', 'Old Dengzhou was the Tang–Song port for Korea and Japan. The First Emperor and Emperor Wu came here seeking immortals, and the mirages off Penglai Pavilion are legendary. Qi Jiguang trained his navy here in the Ming.'],
  ['weihai', '北洋水师基地', 'Base of the Beiyang Fleet', '明代为防倭设威海卫。清末北洋水师在刘公岛设基地，1895年在甲午战争中全军覆没。后被英国租借，1930年收回。', 'Weihai was a Ming garrison against pirates. The Beiyang Fleet was based on Liugong Island and destroyed there in 1895. Leased to Britain afterwards, it was returned in 1930.'],
  ['qingdao', '红瓦绿树 · 碧海蓝天', 'Red roofs and green trees by a blue sea', '青岛原是胶州湾边的小渔村，1898年被德国租借后建港筑城。1914年日本夺取青岛，巴黎和会上的山东问题引发了五四运动。', 'A fishing village on Jiaozhou Bay, Qingdao was built up as a port by Germany from 1898. Japan seized it in 1914, and the Shandong question at Versailles sparked the May Fourth Movement.'],
  ['zhenjiang', '天下第一江山', 'Finest river and hills under heaven', '镇江古称京口，与扬州隔江相对，是运河与长江的交汇点。三国孙权曾在此筑城，金山、焦山、北固山风景闻名。鸦片战争中守军在此奋勇抵抗。', 'Ancient Jingkou faces Yangzhou where the canal crosses the Yangtze. Sun Quan walled it in the Three Kingdoms, and its Jinshan, Jiaoshan and Beigu hills are famous. Its garrison fought hard in the Opium War.'],
  ['sh', '东方巴黎', 'The Paris of the East', '上海元代设县，明清是棉纺业和航运的重镇。1843年开埠后租界迅速扩张，成为远东最大的都市和金融中心。1921年中国共产党在此成立。', 'Made a county under the Yuan, Shanghai was a cotton and shipping town in Ming and Qing. After 1843 the foreign settlements made it the greatest city and money market of the Far East. The Communist Party was founded here in 1921.'],
  ['shaoxing', '越国故都 · 水乡', 'Capital of Yue · a city of waterways', '绍兴是春秋越国的都城，勾践卧薪尝胆的故事发生在这里。王羲之在兰亭写下《兰亭集序》，陆游、王阳明、鲁迅都是绍兴人。', 'Shaoxing was the Yue capital where Goujian slept on brushwood to keep his revenge alive. Wang Xizhi wrote his Orchid Pavilion preface here, and Lu You, Wang Yangming and Lu Xun were natives.'],
  ['ningbo', '海上丝路港口', 'A port of the maritime Silk Road', '宁波古称明州，唐宋时是通往日本、高丽的主要港口，明代为对日勘合贸易的指定口岸。1842年成为五口通商之一，宁波商帮影响遍及全国。', 'Ancient Mingzhou was the main port for Japan and Korea under the Tang and Song and the licensed port for Japan under the Ming. A treaty port from 1842, its merchants spread across China.'],
  ['wenzhou', '瓯越 · 南戏故乡', 'Ou-Yue · home of Southern drama', '温州古为东瓯国之地，宋代南戏在此诞生。它山多地少，人们善于经商，改革开放后的“温州模式”闻名全国。', 'Once the land of the Dong\'ou kingdom, Wenzhou gave birth to Southern drama in the Song. Its hilly, crowded land made its people traders, and the "Wenzhou model" became famous after the reforms.'],
  ['xiamen', '鹭岛', 'Egret Island', '厦门明代筑城防倭，郑成功以此为抗清基地。1842年开埠，近代华侨陈嘉庚在此创办厦门大学。1980年设立经济特区。', 'Walled against pirates in the Ming, Xiamen was Zheng Chenggong\'s base against the Qing. A treaty port from 1842, it gained Xiamen University from the overseas Chinese Tan Kah Kee, and became a special economic zone in 1980.'],
  ['chaozhou', '岭海名邦', 'A famous city of the southern coast', '潮州是潮汕文化的中心，唐代韩愈被贬至此，兴学治鳄，潮人为纪念他把江山都改姓韩。广济桥是中国古代著名的开合式浮桥。', 'Chaozhou is the heart of Teochew culture. Han Yu, exiled here in the Tang, founded schools and drove off crocodiles, and the people renamed river and hill after him. Its Guangji Bridge is a famous opening pontoon bridge.'],
  ['shaoguan', '岭南门户', 'Gateway to Lingnan', '韶关扼守北江上游，唐代张九龄开凿大庾岭新路，从此成为南北交通的要道。禅宗六祖慧能在附近的南华寺弘法。', 'On the upper North River, it became a main road between north and south after Zhang Jiuling cut the Dayu Pass road. Huineng, the Sixth Patriarch of Chan, taught at nearby Nanhua Temple.'],
  ['zhaoqing', '端砚之乡 · 两广总督府', 'Home of Duan inkstones · seat of the Liangguang governor', '肇庆古称端州，出产名列四大名砚之首的端砚。明代两广总督驻此，利玛窦在此建立了中国内地第一座天主教堂。南明永历帝也在此即位。', 'Ancient Duanzhou produced the finest inkstones. The Ming Liangguang governor sat here, Matteo Ricci built the first church of inland China here, and the Southern Ming Yongli emperor was enthroned here.'],
  ['hk', '东方之珠', 'Pearl of the Orient', '香港原属广东新安县，1842年鸦片战争后被割让给英国，后来又被英国租借新界。它逐渐成为国际贸易和金融中心，1997年回归中国。', 'Part of Xin\'an county in Guangdong, Hong Kong was ceded to Britain after the Opium War in 1842, with the New Territories leased later. It grew into a world centre of trade and finance and returned to China in 1997.'],
  ['macau', '中西交汇之城', 'Where East met West', '1557年起葡萄牙人获准在澳门居留贸易，这里成为中西交流的窗口，利玛窦等传教士由此进入内地。1999年澳门回归中国。', 'From 1557 the Portuguese were allowed to live and trade at Macau, which became the window between China and the West; missionaries such as Ricci entered China from here. It returned to China in 1999.'],
  ['haikou', '琼州 · 海南门户', 'Qiongzhou · gateway to Hainan', '汉武帝时在海南设珠崖、儋耳郡，此后历代在岛上设州县。海口所在的琼州是海南的中心，海瑞、丘濬都是琼山人。1988年海南建省。', 'Emperor Wu of the Han set up the first commanderies on Hainan. Qiongzhou, at Haikou, became the island\'s centre, home of Hai Rui and Qiu Jun. Hainan became a province in 1988.'],
  ['guilin', '桂林山水', 'The landscape of Guilin', '秦始皇开凿灵渠，沟通湘江与漓江，桂林由此成为岭南的门户。它的喀斯特山水自古被称为“甲天下”。抗战时文化人云集，号称“文化城”。', 'The Qin Lingqu canal joined the Xiang and Li rivers and made Guilin the gateway to the south. Its karst peaks have long been called the finest scenery under heaven. In the war so many writers came that it was called the City of Culture.'],
  ['liuzhou', '龙城', 'Dragon City', '柳州唐代设州，柳宗元任刺史时开凿水井、兴办学校，后人在此建柳侯祠纪念他。今天它是广西的工业中心。', 'A Tang prefecture, Liuzhou is remembered for Liu Zongyuan, who dug wells and founded schools as governor; his shrine stands here. It is now Guangxi\'s industrial centre.'],
  ['cq', '山城 · 战时陪都', 'Mountain city · the wartime capital', '重庆古为巴国之地，南宋光宗时得名。南宋军民在附近钓鱼城抗击蒙古三十余年。抗战时期它是国民政府的陪都，在日机长期轰炸下坚持不屈。', 'Chongqing was once the land of Ba and took its name under the Song emperor Guangzong. Nearby Diaoyu fortress held off the Mongols for over thirty years. In the war against Japan it was the wartime capital, enduring years of bombing.'],
  ['leshan', '乐山大佛', 'The Great Buddha of Leshan', '乐山古称嘉州，位于岷江、青衣江、大渡河三江汇流处。唐代僧人海通为减轻水患发愿开凿大佛，历时九十年完成，是世界上最大的古代石刻坐佛。', 'Old Jiazhou stands where three rivers meet. The monk Haitong began the Great Buddha to calm the waters; it took ninety years and is the largest ancient carved seated Buddha in the world.'],
  ['langzhong', '阆苑仙境 · 巴蜀要冲', 'A fairy garden · key to Ba-Shu', '阆中位于嘉陵江中游，三国时张飞镇守于此。古城保留了唐宋以来的街巷格局，是古代科举考场保存最完整的地方之一。', 'On the middle Jialing, Langzhong was held by Zhang Fei in the Three Kingdoms. Its old town keeps a street plan from Tang and Song times and one of the best-preserved examination halls.'],
  ['km', '春城', 'City of eternal spring', '昆明在南诏时修建拓东城，元代赛典赤把云南的行政中心移到这里。抗战时西南联合大学在此办学，滇缅公路从这里出发。', 'Kunming began as Nanzhao\'s Tuodong city, and the Yuan governor Sayyid Ajall made it the capital of Yunnan. In the war the Southwest Associated University taught here and the Burma Road began here.'],
  ['dali', '南诏大理故都', 'Old capital of Nanzhao and Dali', '洱海之滨的大理是南诏和大理国的都城，两国统治云南五百多年。崇圣寺三塔是这一时期的遗存。1253年忽必烈远征灭大理，云南从此纳入中央王朝。', 'On Lake Erhai, Dali was the capital of Nanzhao and the Dali kingdom, which ruled Yunnan for over five centuries. The Three Pagodas survive from that time. Khubilai conquered it in 1253, bringing Yunnan into the empire.'],
  ['lijiang', '纳西古城', 'The old Naxi town', '丽江是纳西族的聚居地，明代木氏土司世代统治这里。古城依水而建，没有城墙，保存了独特的东巴文化。', 'Lijiang is the home of the Naxi, long ruled by the hereditary Mu chieftains. Its wall-less old town is built along streams and keeps the Dongba culture alive.'],
  ['guiyang', '林城 · 黔中', 'Forest city · heart of Guizhou', '贵阳元代筑顺元城，明代1413年贵州建省后成为省会。王阳明在附近龙场悟道，开创心学。', 'Built as Shunyuan under the Yuan, Guiyang became the capital when Guizhou became a province in 1413. Wang Yangming had his enlightenment at nearby Longchang.'],
  ['zunyi', '转折之城', 'City of the turning point', '遵义古为播州，杨氏土司统治七百多年，1600年被明朝平定。1935年红军长征途中在此召开遵义会议，成为中国革命的转折点。', 'Once Bozhou, ruled by the Yang chieftains for seven centuries until the Ming crushed them in 1600. The Zunyi conference held here during the Long March in 1935 was a turning point of the revolution.'],
  ['yueyang', '岳阳楼 · 洞庭湖', 'Yueyang Tower on Lake Dongting', '岳阳位于洞庭湖与长江交汇处，三国时鲁肃在此训练水军。范仲淹的《岳阳楼记》写下“先天下之忧而忧，后天下之乐而乐”，使岳阳楼名扬千古。', 'Where Lake Dongting meets the Yangtze, it was Lu Su\'s naval base in the Three Kingdoms. Fan Zhongyan\'s essay on its tower — "first to worry, last to rejoice" — made it famous for ever.'],
  ['ganzhou', '宋城 · 赣南重镇', 'A Song walled city · bastion of southern Jiangxi', '赣州位于章江、贡江合流处，宋代城墙至今仍有数公里保存。它是江西通往广东的要道，王阳明曾在此巡抚南赣。', 'At the meeting of the Zhang and Gong rivers, Ganzhou still has kilometres of Song wall. On the road from Jiangxi to Guangdong, it was where Wang Yangming governed the southern hills.'],
  ['ruijin', '红色故都', 'The red capital', '1931年中华苏维埃共和国临时中央政府在瑞金成立，这里成为中央革命根据地的中心。1934年红军从这一带出发开始长征。', 'The Chinese Soviet Republic was proclaimed at Ruijin in 1931, making it the centre of the Central Soviet Area. The Red Army set out on the Long March from here in 1934.'],
  ['huaian', '运河之都', 'Capital of the canal', '淮安位于运河与淮河的交汇处，明清时漕运总督驻此，掌管全国漕粮北运。韩信、吴承恩、周恩来都出生在这里。', 'Where the canal crosses the Huai, Huai\'an was the seat of the Ming–Qing director-general of grain transport. Han Xin, Wu Cheng\'en and Zhou Enlai were all born here.'],
  ['linqing', '运河商埠', 'A canal emporium', '临清在会通河与卫河交汇处，明代是运河上最繁华的商埠之一，设钞关征收商税。北京的城砖很多是在这里烧造后沿运河运去的。', 'Where the Huitong Canal met the Wei, Linqing was one of the busiest Ming canal towns, with its own customs house. Many of Beijing\'s wall bricks were fired here and shipped up the canal.'],
  ['shg', '天下第一关', 'First pass under heaven', '山海关北倚燕山、南临渤海，明初徐达在此建关，是长城东端的要隘。1644年吴三桂在此引清兵入关，改变了中国历史的走向。', 'Between the Yan mountains and the Bohai Sea, the pass was built by Xu Da in the early Ming at the eastern end of the Wall. In 1644 Wu Sangui let the Qing armies through here, changing the course of Chinese history.'],
  ['zjk', '张库大道起点', 'Start of the Zhangjiakou–Urga road', '张家口是长城的重要关口，明代在此开设马市与蒙古互市。清代张库大道从这里通往库伦和恰克图，茶叶、皮毛贸易兴盛。', 'A major gate in the Wall, Zhangjiakou hosted Ming horse markets with the Mongols. In the Qing the caravan road to Urga and Kyakhta started here, carrying tea and furs.'],
  ['pingyao', '票号之乡', 'Home of the draft banks', '平遥古城保留了明清的城墙和街巷。1823年日升昌票号在这里创办，山西票号此后汇通天下，平遥成为清代的金融中心之一。', 'Pingyao keeps its Ming–Qing walls and streets. The Rishengchang draft bank opened here in 1823, and Shanxi banks soon handled remittances across the empire.'],
  ['taipei', '台湾政经中心', 'Political and economic centre of Taiwan', '台北盆地在清代随移民开垦而兴起，1875年设台北府，1885年台湾建省后为省会。日本殖民统治时期总督府设于此，1945年台湾光复。', 'The Taipei basin grew with settlers in the Qing; Taipei Prefecture was created in 1875 and became the capital when Taiwan was made a province in 1885. The Japanese colonial government sat here until Taiwan was returned in 1945.'],
  ['tainan', '台湾府城', 'The old capital of Taiwan', '台南是台湾开发最早的城市，荷兰人在此筑热兰遮城。1661年郑成功驱逐荷兰人，以此为根据地；清代台湾府设于此两百年，孔庙与赤嵌楼保存至今。', 'Tainan is the oldest city of Taiwan, where the Dutch built Fort Zeelandia. Zheng Chenggong drove them out in 1661 and made it his base; for two centuries it was the Qing prefectural seat, and its Confucian temple and Chikan Tower survive.'],
  ['ny', '南都 · 宛', 'The southern capital · Wan', '南阳古称宛，是战国秦汉时冶铁和商业的大都会。东汉光武帝刘秀从这里起兵，南阳因此被称为“南都”，张衡、张仲景都是南阳人。', 'Ancient Wan was a great centre of iron and trade in Warring States and Han times. The Eastern Han founder rose from here, so it was called the Southern Capital; Zhang Heng and Zhang Zhongjing were natives.'],
  ['shenzhen', '特区之城', 'City of the special zone', '深圳原是宝安县的边境小镇，1980年成为经济特区，在几十年间发展为人口上千万的现代化城市和科技中心，是改革开放的象征。', 'Once a small border town in Bao\'an county, Shenzhen became a special economic zone in 1980 and grew within decades into a high-tech city of over ten million, the symbol of reform and opening.'],
];

export const CITIES: Content['cities'] = CL.map(([site, tzh, ten, dzh, den]) => {
  const s = S[site];
  if (!s) throw new Error(`places-late: unknown city site ${site}`);
  return { modern: i18n(s[0], s[1]), lon: s[2], lat: s[3], tag: i18n(tzh, ten), desc: i18n(dzh, den) };
});

