export const GAZETTEER: Content['gazetteer'] = GZ.map(([zh, en, aliases, site]) => {
  const s = typeof site === 'string' ? S[site] : site;
  if (!s) throw new Error(`places-late: unknown gazetteer site ${site}`);
  return { name: i18n(zh, en), aliases, modern: i18n(s[0], s[1]), lon: s[2], lat: s[3] };
});
